INSERT INTO community_actions (id, title, description, category, organizer, start_at, end_at, location_name, address, lat, lng, points_reward, capacity, image_url, image_credit, status, created_by, created_at) VALUES
  (1, 'Plantăm copaci pe Faleza Mureșului', 'Plantăm 120 de tei și stejari împreună cu Direcția Spații Verzi. Primești mănuși și unelte; vino îmbrăcat pentru grădinărit. Potrivit și pentru familii cu copii de peste 10 ani.', 'ENVIRONMENT', 'Direcția Spații Verzi', '2026-11-07 10:00:00+02', '2026-11-07 13:00:00+02', 'Faleza Mureșului, punctul de întâlnire de la foișor', 'Faleza Mureșului, Arad', 46.1745, 21.3215, 50, 40, '/img/actiune-plantare-copaci.jpg', 'Foto: U.S. Air Force, Christopher Tam · Domeniu public · Wikimedia Commons', 'PUBLISHED', 4, '2026-10-28 12:00:00+02'),
  (2, 'Curățenie în Pădurea Ceala', 'Strângem deșeurile de pe traseele din Lunca Mureșului. Saci și mănuși de la Primărie; încălțăminte impermeabilă recomandată.', 'ENVIRONMENT', 'Parcul Natural Lunca Mureșului', '2026-11-08 09:00:00+02', '2026-11-08 12:00:00+02', 'Pădurea Ceala, parcarea de la intrare', 'Lunca Mureșului, Arad', 46.19, 21.265, 40, 60, '/img/actiune-curatenie.jpg', 'Foto: David Lally · CC BY-SA 2.0 · Wikimedia Commons', 'PUBLISHED', 4, '2026-10-28 12:00:00+02'),
  (3, 'Donăm sânge pentru spitalele din Arad', 'Vino nemâncat de dulciuri, odihnit și cu buletinul. Donarea durează 30 de minute; primești o zi liberă de la angajator și punctele în aplicație.', 'HEALTH', 'Centrul de Transfuzie Sanguină', '2026-11-10 08:00:00+02', '2026-11-10 13:00:00+02', 'Centrul de Transfuzie Sanguină Arad', 'Str. Andrei Șaguna, Arad', 46.1801, 21.309, 80, 30, '/img/actiune-donare-sange.jpg', 'Foto: Shixart1985 · CC BY 2.0 · Wikimedia Commons', 'PUBLISHED', 4, '2026-10-28 12:00:00+02'),
  (4, 'Vopsim gardul Grădiniței nr. 12', 'Vopsim și reparăm gardul împreună cu părinții. Materiale asigurate de Primărie. Vino în haine de lucru.', 'SOCIAL', 'Direcția Învățământ', '2026-11-21 09:00:00+02', '2026-11-21 12:00:00+02', 'Grădinița nr. 12, Str. Lucian Blaga', 'Str. Lucian Blaga, Arad', 46.179, 21.32, 60, 20, NULL, NULL, 'DRAFT', 4, '2026-10-28 12:00:00+02'),
  (5, 'Plantăm tei în Parcul Copiilor', 'Acțiune încheiată. Mulțumim tuturor celor care au venit!', 'ENVIRONMENT', 'Direcția Spații Verzi', '2026-03-21 10:00:00+02', '2026-03-21 13:00:00+02', 'Parcul Copiilor, intrarea dinspre Faleză', NULL, 46.1738, 21.3205, 50, 40, NULL, NULL, 'DONE', 4, '2026-03-15 12:00:00+02'),
  (6, 'Curățenie de primăvară pe Faleza Mureșului', 'Acțiune încheiată. Mulțumim tuturor celor care au venit!', 'ENVIRONMENT', 'Direcția Spații Verzi', '2026-04-18 09:00:00+03', '2026-04-18 12:00:00+03', 'Faleza Mureșului, foișorul de lângă Podul Traian', NULL, 46.1752, 21.3232, 40, 60, NULL, NULL, 'DONE', 4, '2026-04-12 12:00:00+03'),
  (7, 'Donăm sânge de Ziua Mondială a Sănătății', 'Acțiune încheiată. Fiecare donare poate salva până la trei vieți.', 'HEALTH', 'Centrul de Transfuzie Sanguină', '2026-05-12 08:00:00+03', '2026-05-12 13:00:00+03', 'Centrul de Transfuzie Sanguină Arad', NULL, 46.1801, 21.309, 80, 30, NULL, NULL, 'DONE', 4, '2026-05-06 12:00:00+03'),
  (8, 'Atelier de reciclare cu copiii', 'Acțiune încheiată. Mulțumim pentru implicare!', 'SOCIAL', 'Direcția de Asistență Socială', '2026-06-06 10:00:00+03', '2026-06-06 12:00:00+03', 'Parcul Eminescu, scena de vară', NULL, 46.175, 21.319, 30, 25, NULL, NULL, 'DONE', 4, '2026-05-31 12:00:00+03'),
  (9, 'Ecologizăm malul de la Ștrandul Neptun', 'Acțiune încheiată. Mulțumim tuturor celor care au venit!', 'ENVIRONMENT', 'Parcul Natural Lunca Mureșului', '2026-07-11 09:00:00+03', '2026-07-11 12:00:00+03', 'Ștrandul Neptun, parcarea principală', NULL, 46.169, 21.329, 40, 50, NULL, NULL, 'DONE', 4, '2026-07-05 12:00:00+03'),
  (10, 'Ghizi voluntari la Zilele Aradului', 'Acțiune încheiată. Mulțumim ghizilor voluntari!', 'CULTURE', 'Centrul Municipal de Cultură', '2026-09-12 10:00:00+03', '2026-09-12 18:00:00+03', 'Piața Avram Iancu', NULL, 46.1726, 21.3153, 60, 30, NULL, NULL, 'DONE', 4, '2026-09-06 12:00:00+03'),
  (11, 'Plantare de toamnă pe Calea Victoriei', 'Acțiune încheiată. Mulțumim tuturor celor care au venit!', 'ENVIRONMENT', 'Direcția Spații Verzi', '2026-10-10 10:00:00+03', '2026-10-10 13:00:00+03', 'Calea Victoriei, în fața Palatului Cultural', NULL, 46.1757, 21.3171, 50, 40, NULL, NULL, 'DONE', 4, '2026-10-04 12:00:00+03'),
  (12, 'Donăm sânge pentru spitalele din Arad (octombrie)', 'Acțiune încheiată. Fiecare donare poate salva până la trei vieți.', 'HEALTH', 'Centrul de Transfuzie Sanguină', '2026-10-20 08:00:00+03', '2026-10-20 13:00:00+03', 'Centrul de Transfuzie Sanguină Arad', NULL, 46.1801, 21.309, 80, 30, NULL, NULL, 'DONE', 4, '2026-10-14 12:00:00+03'),
  (13, 'Curățenie în Pădurea Ceala (etapa 1)', 'Acțiune încheiată. Mulțumim tuturor celor care au venit!', 'ENVIRONMENT', 'Parcul Natural Lunca Mureșului', '2026-10-25 09:00:00+02', '2026-10-25 12:00:00+02', 'Pădurea Ceala, parcarea de la intrare', NULL, 46.19, 21.265, 40, 60, NULL, NULL, 'DONE', 4, '2026-10-19 12:00:00+03'),
  (14, 'Plantăm bulbi de lalele în Parcul Eminescu', 'Acțiune încheiată. Mulțumim tuturor celor care au venit!', 'ENVIRONMENT', 'Direcția Spații Verzi', '2026-11-01 10:00:00+02', '2026-11-01 12:00:00+02', 'Parcul Eminescu, aleea centrală', NULL, 46.175, 21.319, 50, 40, NULL, NULL, 'DONE', 4, '2026-10-26 12:00:00+02'),
  (15, 'Strângem haine pentru adăpostul de iarnă', 'Acțiune încheiată. Mulțumim pentru implicare!', 'SOCIAL', 'Direcția de Asistență Socială', '2026-11-03 16:00:00+02', '2026-11-03 19:00:00+02', 'Primăria Arad, Bd. Revoluției 75', NULL, 46.1768, 21.3145, 60, 40, NULL, NULL, 'DONE', 4, '2026-10-28 12:00:00+02')
