-- contoarele denormalizate = rândurile reale
UPDATE community_actions a SET
  registered_count = (SELECT count(*) FROM community_registrations r WHERE r.action_id = a.id AND r.status IN ('REGISTERED','CONFIRMED')),
  confirmed_count  = (SELECT count(*) FROM community_registrations r WHERE r.action_id = a.id AND r.status = 'CONFIRMED');

-- sold = suma tranzacțiilor (pentru toți cei care au tranzacții)
UPDATE users u SET points_balance = t.total
FROM (SELECT user_id, SUM(amount) AS total FROM points_transactions GROUP BY user_id) t
WHERE u.id = t.user_id;

SELECT setval('users_id_seq', (SELECT MAX(id) FROM users));
SELECT setval('community_actions_id_seq', (SELECT MAX(id) FROM community_actions));
SELECT setval('community_registrations_id_seq', (SELECT MAX(id) FROM community_registrations));
SELECT setval('points_transactions_id_seq', GREATEST((SELECT MAX(id) FROM points_transactions), 1));

